 check('HTTP whitelist and final source fields reach actual IPC',latest.some(e=>e.metadata?.httpStatus===200&&e.outcome?.responseModel==='physical-offline'&&e.outcome.costTotal===0.12&&e.outcome.costSource==='provider'));
