  const worker=fork(join(dirname(entry),'pi-worker.js'),['--mode','subagent'],{cwd:repo,execPath:executable,execArgv:['--require',guard],env,serialization:'advanced',stdio:['ignore','ignore','pipe','ipc'],windowsHide:true});
  let n=0,workerReady;const waiting=new Map(),workerEvents=[],workerCollect=new Set();const readyWorker=new Promise(resolve=>{workerReady=resolve;});
